from fastapi import FastAPI
from pydantic import BaseModel

app = FastAPI()

class Invite(BaseModel):
    name: str
    guests: list

    @classmethod
    def __get_validators__(cls):
        yield cls.validate

    @classmethod
    def validate(cls, v):
        if len(v.guests) > 10:
            return False
        return True

@app.post("/send_invite")
def send_invite(invite: Invite):
    message = f"Dear {invite.name},\n\nYou are invited to our dinner party with these guests: \n{', '.join(invite.guests)}"
    return message

