from fastapi import FastAPI, Form
from pydantic import BaseModel

app = FastAPI()

class Event(BaseModel):
    title: str
    description: str
    venue: str
    date: str
    time: str
    attendees: list[str]

@app.post("/event")
async def create_event(event: Event):
    event_dict = event.dict()
    attendee_emails = [attendee.split()[1] for attendee in event_dict['attendees']]

    event_info = f"""
    Title: {event_dict['title']}
    Description: {event_dict['description']}
    Venue: {event_dict['venue']}
    Date: {event_dict['date']}
    Time: {event_dict['time']}
    Attendees: {attendee_emails}
    """
    return event_info

def dinner_guests():
    guests = {'Alice': 'author', 'Bob': 'painter', 'Charlie': 'musician', 'Dave': 'philosopher'}
    return guests

def menu(guests):
    menu_items = {
        'author': ['Salad', 'Steak'],
        'painter': ['Pasta', 'Chocolate cake'],
        'musician': ['Sandwich', 'Cheeseburger'],
        'philosopher': ['Lobster', 'Caviar']
    }

    meal_choices = {}
    for name, profession in guests.items():
        meal_choices[name] = menu_items[profession][0]

    return meal_choices

def invite(guests):
    meal = menu(guests)
    for name, food in meal.items():
        print('Dear {}, {} will be brought for you at the party on Saturday.'.format(name, food))

